const items = $input.all();

const filasHTML = items.map(i => `
    <tr>
        <td>${i.json.codigo}</td>
        <td>${i.json.producto}</td>
        <td>${i.json.categoria}</td>
        <td>Q${parseFloat(i.json.precio_anterior).toFixed(2)}</td>
        <td><b>Q${parseFloat(i.json.precio_nuevo).toFixed(2)}</b></td>
        <td>${parseFloat(i.json.diferencia) >= 0 ? '+' : ''}Q${parseFloat(i.json.diferencia).toFixed(2)}</td>
        <td>${i.json.cambio_porcentaje}%</td>
        <td>${i.json.fecha}</td>
    </tr>
`).join('');

const telegramMsg = ` Historial de cambios de precio
${new Date().toLocaleDateString('es-GT')}

Total cambios: ${items.length}

Últimos cambios:
${items.slice(0,5).map(i =>
    ` ${i.json.producto}\n   Anterior: Q${parseFloat(i.json.precio_anterior).toFixed(2)} → Nuevo: Q${parseFloat(i.json.precio_nuevo).toFixed(2)} (${i.json.cambio_porcentaje}%)`
).join('\n')}

Ver tabla completa en su correo.`;

return [{
    json: {
        total: items.length,
        filas_html: filasHTML,
        telegram: telegramMsg
    }
}];
